head.script:
// 전역 변수 - 업로드된 이미지 파일
scwin.projectImageFile = null;

scwin.onpageload = function() {
    // 모달 초기화
    scwin.initModal();
};

scwin.modalClose = function(argRuntimeID) {
    try {
        // 팝업 객체 접근
        let popObj = $p.getPopupWindow(argRuntimeID);

        // 모달 상태 초기화
        scwin.modalManager.isModalOpen = false;
        scwin.modalManager.modalInstance = null;

        return true; // 팝업 닫기 허용

    } catch (e) {

        // 오류가 있어도 레이아웃과 모달 상태는 초기화
        scwin.modalManager.isModalOpen = false;
        scwin.modalManager.modalInstance = null;

        return true; // 팝업 닫기 허용
    }
}

// 모달 초기화
scwin.initModal = function() {
    try {
        // 팝업 파라미터에서 userName 가져오기 - dataObject 방식
        let popupParam = $p.getParameter("project_param");
        let userName = "식스센스"; // 기본값
        if (popupParam && popupParam.userName) {
            userName = popupParam.userName;
        }

        // 팀장 인풋을 읽기전용으로 설정
        if (input_userName) {
            input_userName.setValue(userName);
            input_userName.setReadOnly(true);
        }

        // 메일 전송 시각을 09:00으로 설정
        if (input_emailTime) {
            input_emailTime.setValue("09:00");
            input_emailTime.setReadOnly(true);
        }

    } catch(e) {
    }
};

// 저장 버튼 클릭
scwin.btn_save_onclick = function(e) {
    try {
        let projectName = dm_projectForm.get("projectName");
        // let userName = dm_projectForm.get("userName");
        let popupParam = $p.getParameter("project_param");
        // let modalId = $p.parent().scwin.modalManager.modalId;
        if (!projectName || projectName.trim() === "") {
            $c.win.alert("프로젝트명을 입력해주세요.");
            return;
        }

        // 메일 전송 시각을 09:00으로 고정 설정
        const emailSendTime = "09:00";
        dm_projectForm.set("emailSendTime", emailSendTime);
        dm_projectForm.set("userId",popupParam.userId);
        dm_projectForm.set("description",input_description.getValue());

        const formData = new FormData();

        // 프로젝트 기본 정보 추가
        formData.append("projectName", projectName);
        formData.append("description", input_description.getValue());
        formData.append("emailSendTime", emailSendTime);
        formData.append("userId", popupParam.userId);

        // 이미지 파일이 있으면 추가
        if (scwin.projectImageFile) {
            formData.append("file", scwin.projectImageFile);
        }
        // Ajax 요청으로 전송
        $.ajax({
            url: "/InsWebApp/project/create.pwkjson",
            type: "POST",
            data: formData,
            processData: false, // 파일 업로드를 위해 필수
            contentType: false, // 파일 업로드를 위해 필수
            success: function(response) {
                scwin.handleSaveSuccess(response);
            },
            error: function(xhr, status, error) {
                scwin.handleSaveError(xhr, status, error);
            }
        });
    } catch(e) {
        $c.win.alert("프로젝트 저장 중 오류가 발생했습니다.");
        scwin.modalClose(scwin.modalId,modalArgJsnInfo);
    }
};

// Ajax 성공 시 처리
scwin.handleSaveSuccess = function(response) {
    try {
        // 서버 응답 검증
        const elHeader = response && response.elHeader;
        if (elHeader && elHeader.resSuc === false) {
            $c.win.alert("에러코드: " + elHeader.resCode + "\n에러메시지: " + elHeader.resMsg);
            return;
        }

        $c.win.alert("프로젝트가 성공적으로 저장되었습니다!");

        // 부모 창의 refreshSideMenu 함수 호출 (사이드메뉴 새로고침)
        const parentFrame = $p.parent();
        if (parentFrame && parentFrame.scwin && parentFrame.scwin.refreshSideMenu) {
            parentFrame.scwin.refreshSideMenu();
        }

        // 메인 콘텐츠의 프로젝트 카드도 갱신
        if (parentFrame && parentFrame.scwin && parentFrame.scwin.refreshMainContent) {
            parentFrame.scwin.refreshMainContent();
        }


        try {
            if (typeof $p.closePopup === 'function') {
                $p.closePopup();
            } 
        } catch (closeError) {
        }

    } catch (error) {
        $c.win.alert("프로젝트가 저장되었지만 화면 처리 중 오류가 발생했습니다.");

        // 오류가 발생해도 팝업은 닫기 시도
        try {
            if (typeof $p.closePopup === 'function') {
                $p.closePopup();
            } else if (window.close) {
                window.close();
            }
        } catch (closeError) {
        }
    }
};

// Ajax 실패 시 처리
scwin.handleSaveError = function(xhr, status, error) {

    let errorMessage = "프로젝트 저장 중 오류가 발생했습니다.";

    if (xhr.responseJSON && xhr.responseJSON.elHeader) {
        const elHeader = xhr.responseJSON.elHeader;
        errorMessage += "\n에러코드: " + elHeader.resCode + "\n에러메시지: " + elHeader.resMsg;
    } else if (xhr.responseText) {
        errorMessage += "\n상세: " + xhr.responseText;
    }

    $c.win.alert(errorMessage);
};

// 이름 입력 키보드 이벤트
scwin.input_name_onkeyup = function(e) {
    dm_projectForm.set("projectName", e.target.value);
};

// 프로젝트 이미지 버튼 클릭 (메인 이미지 영역 클릭)
scwin.btn_projectImage_onclick = function(e) {
    $p.$("#fileInput_projectImage").click();
    $p.$("#fileInput_projectImage").on("change", scwin.fileInput_change);
};

// 업로드 아이콘 버튼 클릭 (우상단 카메라 아이콘 클릭)
scwin.btn_uploadIcon_onclick = function(e) {
    $p.$("#fileInput_projectImage").click();
    $p.$("#fileInput_projectImage").on("change", scwin.fileInput_change);
};

// 파일 선택 시 처리
scwin.fileInput_change = function(e) {
    try {

        const fileInput = $p.$("#fileInput_projectImage").get(0);
        const file = fileInput.files[0];

        if (!file) {
            return;
        }


        // 파일 타입 검증
        if (!file.type.startsWith('image/')) {
            $c.win.alert('이미지 파일만 업로드할 수 있습니다.');
            return;
        }

        // 파일 크기 검증 (10MB 제한)
        if (file.size > 10 * 1024 * 1024) {
            $c.win.alert('파일 크기가 10MB를 초과합니다.');
            return;
        }

        // 전역 변수에 파일 저장
        scwin.projectImageFile = file;

        // 이미지 미리보기 생성
        const imageUrl = URL.createObjectURL(file);

        // 배경 이미지로 설정하고 스타일 변경
        btn_projectImage.setStyle("background-image", `url('${imageUrl}')`);

        // 파일 업로드 시 점선에서 실선으로 변경
        btn_projectImage.setStyle("border", "2px solid #999");

        // WebSquare에서 버튼 라벨 텍스트 제거하는 올바른 방법
        try {
            // 방법 1: 버튼의 라벨 숨기기
            btn_projectImage.setStyle("color", "transparent");

            // 방법 2: 또는 라벨 내용을 빈 문자열로 설정
            if (btn_projectImage.setLabel) {
                btn_projectImage.setLabel("");
            }
        } catch(labelError) {
        }

    } catch(error) {
        $c.win.alert("파일 처리 중 오류가 발생했습니다.");
    }
};

// 시간 입력 검증 (사용하지 않지만 호환성을 위해 유지)
scwin.validateTimeInput = function(inputValue, maxValue) {
    const num = parseInt(inputValue);
    if (isNaN(num) || num < 0) {
        return "00";
    } else if (num > maxValue) {
        return String(maxValue).padStart(2, '0');
    } else {
        return String(num).padStart(2, '0');
    }
};
